<?php
 namespace OSS\Model; use OSS\Core\OssException; class RequestPaymentConfig implements XmlConfig { public function __construct($payer = null) { $this->payer = $payer; } public function parseFromXml($strXml) { $xml = simplexml_load_string($strXml); if (isset($xml->Payer)) { $this->payer = strval($xml->Payer); } } public function serializeToXml() { $xml = new \SimpleXMLElement('<?xml version="1.0" encoding="utf-8"?><RequestPaymentConfiguration></RequestPaymentConfiguration>'); if (isset($this->payer)) { $xml->addChild('Payer', $this->payer); } return $xml->asXML(); } public function __toString() { return $this->serializeToXml(); } public function getPayer() { return $this->payer; } private $payer = ""; }